import React from "react";

function Dashboard({ data }) {
  if (!data) return null;

  const { analytics, sample_data, insights } = data;

  return (
    <div className="dashboard">
      <h2>📊 Data Analysis</h2>

      {/* Insights */}
      {insights && (
        <div className="card">
          <h3>💡 Insights</h3>
          <p>{insights}</p>
        </div>
      )}

      {/* GPA Distribution */}
      <div className="card">
        <h3>📈 GPA Distribution</h3>
        {analytics?.gpa_distribution?.length ? (
          <ul>
            {analytics.gpa_distribution.map((val, i) => (
              <li key={i}>{val}</li>
            ))}
          </ul>
        ) : (
          <p>No data available</p>
        )}
      </div>

      {/* Performance Breakdown */}
      <div className="card">
        <h3>🏆 Performance Breakdown</h3>
        {analytics?.performance_counts ? (
          <ul>
            {Object.entries(analytics.performance_counts).map(
              ([key, value]) => (
                <li key={key}>
                  {key}: {value}
                </li>
              )
            )}
          </ul>
        ) : (
          <p>No data available</p>
        )}
      </div>

      {/*Cleaned Data */}
      <div className="card">
        <h3>📋 Cleaned Data</h3>

        {sample_data?.length ? (
          <table style={{ width: "100%", borderCollapse: "collapse" }}>
            <thead>
              <tr>
                <th>HS Avg</th>
                <th>GPA</th>
              </tr>
            </thead>
            <tbody>
              {sample_data.slice(0, 5).map((row, index) => (
                <tr key={index}>
                  <td>{row.hs_avg}</td>
                  <td>{row.gpa}</td>
                </tr>
              ))}
            </tbody>
          </table>
        ) : (
          <p>No data available</p>
        )}
      </div>
    </div>
  );
}

export default Dashboard;
